// ---------- armazenamento ----------
const Store={db:null,dl:null,dirty:new Set(),timers:new Map(),chain:new Map(),
  pasta:false,pastaPend:null,
  async init(){
    // mundo numa pasta do PC: no app instalado sempre; no navegador quando a pasta ja tem permissao
    const AP=window.AtlasPasta;if(AP&&AP.suporta()){try{const u=await AP.ultima();if(u&&u.pronta&&await AP.reabrir(false)){await this.dePasta();return}if(u)this.pastaPend=u.nome}catch(e){console.warn("pasta",e)}}
    let db=null;try{if(window.claude&&claude.use){db=await Promise.race([claude.use("db"),new Promise(r=>setTimeout(()=>r(null),9000))]);claude.use("downloads").then(d=>this.dl=d,()=>{})}}catch(e){}
    if(db){this.db=db;let first=0;const done=()=>{if(++first===2)ready()};const t=setTimeout(()=>{if(first<2){first=2;pill("Sem resposta do armazenamento","warn");ready()}},10000);
      for(const kind of["notes","maps"]){let got=false;db.collection(kind).onSnapshot(sn=>{applySnap(kind,sn);if(!got){got=true;done();if(first>=2)clearTimeout(t)}},e=>{pill("Armazenamento indisponível","warn");if(!got){got=true;done()}})}
      pill("Salvo na nuvem","ok")}
    else{for(const kind of["notes","maps"]){try{const raw=JSON.parse(localStorage.getItem("atlas:"+kind)||"[]");for(const o of raw)S[kind].set(o.id,o)}catch(e){}}pill(document.documentElement.classList.contains("android")?"Salvo neste aparelho":"Salvo só neste navegador","warn");ready()}},
  // le a pasta aberta e passa a gravar nela
  async dePasta(migrar){const AP=window.AtlasPasta,r=await AP.carregar();const antes={notes:[...S.notes.values()],maps:[...S.maps.values()]};
    this.pasta=true;this.db=null;this.pastaPend=null;S.notes.clear();S.maps.clear();for(const o of r.notas)S.notes.set(o.id,o);for(const m of r.mapas)S.maps.set(m.id,m);
    if(migrar&&!r.notas.length&&!r.mapas.length&&(antes.notes.length||antes.maps.length)){for(const o of antes.notes){S.notes.set(o.id,o);AP.gravaNota(o)}for(const m of antes.maps){S.maps.set(m.id,m);AP.gravaMapa(m)}if(window.AtlasBatalha&&AtlasBatalha.copiarParaPasta)AtlasBatalha.copiarParaPasta().catch(e=>console.warn(e));if(window.AtlasQuadro&&AtlasQuadro.copiarImgsParaPasta)AtlasQuadro.copiarImgsParaPasta().catch(e=>console.warn(e));toast(antes.notes.length+" nota(s) e "+antes.maps.length+" mapa(s) copiados para a pasta.")}
    pill("Pasta: "+r.nome,"ok");if(booted){S.note=null;S.map=null;drawAll()}else ready()},
  async abrirPasta(){const AP=window.AtlasPasta;if(!AP||!AP.suporta())return toast("Este navegador não abre pastas. Use o Chrome, o Edge ou o app do Atlas.");
    try{const n=await AP.escolher();if(!n)return;await this.dePasta(true);toast("Mundo aberto: "+n)}catch(e){if(e&&e.name==="AbortError")return;console.warn(e);toast(e.message||"Não foi possível abrir a pasta.")}},
  async reabrirPasta(){const AP=window.AtlasPasta;try{if(await AP.reabrir(true))await this.dePasta(false);else toast("Sem permissão para abrir a pasta.")}catch(e){toast("Não foi possível abrir a pasta.")}},
  async fecharPasta(){const AP=window.AtlasPasta;await AP.espera();try{guardaAbas();localStorage.setItem("atlas:irMundos","1")}catch(e){}await AP.fechar();location.reload()},
  save(kind,o){o.updated=now();if(kind==="notes")NV++;if(window.AtlasDrive)AtlasDrive.marca();const key=kind+"/"+o.id;this.dirty.add(key);clearTimeout(this.timers.get(key));pill("Salvando…");
    this.timers.set(key,setTimeout(()=>this.flush(kind,o.id),700))},
  flush(kind,id){const key=kind+"/"+id,o=S[kind].get(id);if(!o){this.dirty.delete(key);return}
    if(this.pasta){const AP=window.AtlasPasta;(kind==="notes"?AP.gravaNota(o):AP.gravaMapa(o)).then(()=>{this.dirty.delete(key);if(!this.dirty.size)pill("Salvo na pasta","ok")},e=>{console.warn(e);pill("Erro ao salvar","warn");toast("Não foi possível gravar na pasta.")});return}
    if(!this.db){this.local(kind);this.dirty.delete(key);pill(document.documentElement.classList.contains("android")?"Salvo neste aparelho":"Salvo só neste navegador","warn");return}
    const body=JSON.parse(JSON.stringify(o));delete body.id;const stamp=o.updated;
    const p=(this.chain.get(key)||Promise.resolve()).then(()=>this.db.doc(key).set(body)).then(()=>{if(S[kind].get(id)&&S[kind].get(id).updated===stamp){this.dirty.delete(key)}if(!this.dirty.size)pill("Salvo","ok")},
      e=>{pill("Erro ao salvar","warn");toast(e&&e.code==="invalid_argument"?"Sem permissão para salvar neste mundo.":"Não foi possível salvar agora. Tente de novo em instantes.")});
    this.chain.set(key,p)},
  local(kind){try{localStorage.setItem("atlas:"+kind,JSON.stringify([...S[kind].values()]))}catch(e){toast("Sem espaço para salvar neste navegador.")}},
  remove(kind,id){const o0=S[kind].get(id);if(kind==="notes")NV++;if(window.AtlasDrive)AtlasDrive.marca();if(this.pasta&&o0){const AP=window.AtlasPasta;(kind==="notes"?AP.apagaNota(o0):AP.apagaMapa(o0)).catch(()=>toast("Não foi possível excluir da pasta."))}S[kind].delete(id);const key=kind+"/"+id;clearTimeout(this.timers.get(key));this.dirty.delete(key);if(this.pasta)return;if(this.db)this.db.doc(key).delete().catch(()=>toast("Não foi possível excluir."));else this.local(kind)}};
function pill(t,c){const p=$("#sync");p.textContent=t;p.className="pill "+(c||"")}
function applySnap(kind,sn){const m=S[kind],seen=new Set(),changed=[];
  for(const d of sn.docs){seen.add(d.id);if(Store.dirty.has(kind+"/"+d.id))continue;const body=JSON.parse(JSON.stringify(d.data()||{}));body.id=d.id;const old=m.get(d.id);
    if(!old||JSON.stringify(old)!==JSON.stringify(body)){m.set(d.id,body);changed.push(d.id)}}
  if(!sn.metadata.fromCache)for(const id of[...m.keys()])if(!seen.has(id)&&!Store.dirty.has(kind+"/"+id)){m.delete(id);changed.push(id)}
  if(!changed.length||!booted)return;drawSide();
  if(kind==="notes"){if(S.sec==="notes"&&changed.includes(S.note)){if(S.notes.has(S.note)){if(document.activeElement&&document.activeElement.classList.contains("ed"))return;drawMain()}else{S.note=null;drawMain()}}if(S.place)drawPlace()}
  else if(S.sec==="maps"&&changed.includes(S.map)){if(!S.maps.has(S.map))S.map=null;drawMain()}}

