// cabecalho: "chave: valor" numa linha; tambem aceita listas YAML do Obsidian (em varias linhas ou [a, b]) e fim de linha do Windows
const tiraAsp=v=>{v=v.trim();let m=/^"(.*)"$/.exec(v);if(m)return m[1].replace(/\\(["\\])/g,"$1");m=/^'(.*)'$/.exec(v);return m?m[1].replace(/''/g,"'"):v};
function fm(src){src=String(src||"");if(src.indexOf("\r")>=0)src=src.replace(/\r\n?/g,"\n");const m=/^---\n([\s\S]*?)\n---[ \t]*\n?/.exec(src);const props={};if(!m)return{props,body:src};let lk=null;
  for(const ln of m[1].split("\n")){const li=/^\s*-\s*(.*)$/.exec(ln);if(li&&lk){const v=tiraAsp(li[1]);if(v)props[lk]=props[lk]?props[lk]+", "+v:v;continue}
    const i=ln.indexOf(":");if(i>0&&!/^\s/.test(ln)){const k=ln.slice(0,i).trim();let v=tiraAsp(ln.slice(i+1));if(v[0]==="["&&v[1]!=="["&&v.endsWith("]")){const its=[];v.slice(1,-1).replace(/\s*("[^"]*"|'[^']*'|[^,]+)\s*(?:,|$)/g,(_,x)=>{const t=tiraAsp(x);if(t)its.push(t);return ""});v=its.join(", ")}props[k]=v;lk=k}}
  return{props,body:src.slice(m[0].length)}}
const norm=t=>String(t||"").trim().toLowerCase();
// indice de titulos e de outros nomes (aliases); refeito quando alguma nota muda
let NV=0;const ALI={v:"",t:null,a:null};
const aliasesDe=o=>{const p=fm(o.content).props,v=p.aliases||p.alias;return v?splitL(v):[]};
function idxNotas(){const k=NV+":"+S.notes.size;if(ALI.v===k)return ALI;const t=new Map(),a=new Map();for(const o of S.notes.values()){const n=norm(o.title);if(!t.has(n))t.set(n,o)}
  for(const o of S.notes.values()){if(o.kind==="canvas")continue;for(const al of aliasesDe(o)){const n=norm(al);if(n&&!t.has(n)&&!a.has(n))a.set(n,o)}}ALI.v=k;ALI.t=t;ALI.a=a;return ALI}
const semSecao=t=>{t=String(t||"");const i=t.indexOf("#");return i>=0?t.slice(0,i):t};
function findNote(title){const n=norm(semSecao(title));if(!n)return null;const I=idxNotas();return I.t.get(n)||I.a.get(n)||null}
// nomes pelos quais uma nota e alcancada (titulo + outros nomes que nao batem com titulo de outra nota)
function nomesDe(o){const I=idxNotas(),L=[norm(o.title)];for(const al of aliasesDe(o)){const n=norm(al);if(I.a.get(n)===o)L.push(n)}return L}
